import { computed, ref } from "vue";
import { sql } from "kysely";
import {
  executeWithEvent,
  generateLocalRuid,
  getRawConnection,
  nowISO,
  rdb,
} from "@/shared/database";

export interface ProductDemoItem {
  id: number;
  ruid: string;
  templateRuid: string | null;
  name: string;
  defaultCode: string | null;
  listPrice: number;
  type: "consu" | "service" | "product";
  active: boolean;
  saleOk: boolean;
  competitor: boolean;
  sequence: number;
  brandName: string | null;
  categoryName: string | null;
  uomName: string | null;
  syncStatus: string;
}

interface ProductDemoStats {
  total: number;
  saleable: number;
  competitor: number;
}

interface ProductDemoSnapshot {
  products: ProductDemoItem[];
  stats: ProductDemoStats;
}

interface DemoLookupRefs {
  brandRuid: string;
  categoryRuid: string;
  uomRuid: string;
}

const productTables = [
  "product_product",
  "product_template",
  "product_brand",
  "product_category",
  "uom_uom",
];
const productPageSize = 100;

const emptyStats: ProductDemoStats = {
  total: 0,
  saleable: 0,
  competitor: 0,
};

function asBool(value: unknown) {
  return value === true || value === 1 || value === "1";
}

function mapProduct(row: any): ProductDemoItem {
  return {
    id: row.id,
    ruid: row._ruid,
    templateRuid: row.product_tmpl_id ?? null,
    name: row.name,
    defaultCode: row.default_code,
    listPrice: Number(row.lst_price ?? 0),
    type: row.type ?? "product",
    active: asBool(row.active),
    saleOk: asBool(row.sale_ok),
    competitor: asBool(row.competitor_product),
    sequence: Number(row.custom_sequence ?? 0),
    brandName: row.brand_name ?? null,
    categoryName: row.category_name ?? null,
    uomName: row.uom_name ?? null,
    syncStatus: row._sync_status,
  };
}

async function fetchProductPage(limit: number, offset: number) {
  const rows = await rdb
    .selectFrom("product_product as product")
    .leftJoin("product_template as template", "template._ruid", "product.product_tmpl_id")
    .leftJoin("product_brand as brand", "brand._ruid", "template.brand_id")
    .leftJoin("product_category as category", "category._ruid", "template.categ_id")
    .leftJoin("uom_uom as uom", "uom._ruid", "product.uom_id")
    .select([
      "product.id",
      "product._ruid",
      "product.product_tmpl_id",
      "product.name",
      "product.default_code",
      "product.lst_price",
      "product.type",
      "product.active",
      "product.sale_ok",
      "product.competitor_product",
      "product.custom_sequence",
      "product._sync_status",
      "brand.name as brand_name",
      "category.name as category_name",
      "uom.name as uom_name",
    ])
    .where("product._delete_date", "is", null)
    .orderBy("product.custom_sequence", "desc")
    .orderBy("product.name", "asc")
    .limit(limit)
    .offset(offset)
    .execute();

  return rows.map(mapProduct);
}

async function findOrCreateLookup(
  table: "product_brand" | "product_category" | "uom_uom",
  name: string,
  extra: Record<string, unknown> = {},
) {
  const existing = await rdb
    .selectFrom(table)
    .select(["_ruid"])
    .where("name", "=", name)
    .where("_delete_date", "is", null)
    .executeTakeFirst();

  if (existing?._ruid) return existing._ruid;

  const now = nowISO();
  const ruid = generateLocalRuid();

  await rdb
    .insertInto(table)
    .values({
      _ruid: ruid,
      _create_date: now,
      _write_date: now,
      _delete_date: null,
      _sync_status: "synced",
      name,
      ...extra,
    } as any)
    .execute();

  return ruid;
}

async function ensureDemoLookups(): Promise<DemoLookupRefs> {
  const [brandRuid, categoryRuid, uomRuid] = await Promise.all([
    findOrCreateLookup("product_brand", "Reactive Demo", { active: 1 }),
    findOrCreateLookup("product_category", "Reactive Demo", {
      parent_id: null,
    }),
    findOrCreateLookup("uom_uom", "Unit", { prefix: "u", rounding: 1 }),
  ]);

  return { brandRuid, categoryRuid, uomRuid };
}

function createProductRows(input: {
  name: string;
  price: number;
  type: "consu" | "service" | "product";
  saleOk: boolean;
  competitor: boolean;
  refs: DemoLookupRefs;
}) {
  const now = nowISO();
  const templateRuid = generateLocalRuid();
  const productRuid = generateLocalRuid();
  const sequence = Date.now();

  return {
    template: {
      _ruid: templateRuid,
      _create_date: now,
      _write_date: now,
      _delete_date: null,
      _sync_status: "synced",
      name: input.name,
      sale_ok: input.saleOk ? 1 : 0,
      purchase_ok: 0,
      type: input.type,
      brand_id: input.refs.brandRuid,
      categ_id: input.refs.categoryRuid,
      taxes_id: null,
      competitor_product: input.competitor ? 1 : 0,
      uom_id: input.refs.uomRuid,
    },
    product: {
      _ruid: productRuid,
      _create_date: now,
      _write_date: now,
      _delete_date: null,
      _sync_status: "synced",
      name: input.name,
      default_code: `DEMO-${sequence}`,
      barcode: null,
      color_code: null,
      custom_sequence: sequence,
      lst_price: input.price,
      standard_price: input.price,
      volume: 0,
      weight: 0,
      image_512: null,
      image_ids: null,
      type: input.type,
      product_tmpl_id: templateRuid,
      packaging_ids: null,
      uom_id: input.refs.uomRuid,
      can_sale_in_uom: 1,
      attachment_ids: null,
      competitor_product: input.competitor ? 1 : 0,
      active: 1,
      warehouse_ids: null,
      suggested_price_ids: null,
      sale_ok: input.saleOk ? 1 : 0,
      sub_product_ids: null,
      user_product_limit_ids: null,
      can_be_use_in_promotion: 1,
      product_custom_attribute_1: null,
      product_custom_attribute_2: null,
      product_custom_attribute_3: null,
      product_custom_attribute_4: null,
      product_custom_attribute_5: null,
      product_custom_attribute_6: null,
      product_custom_attribute_7: null,
      product_custom_attribute_8: null,
      product_custom_attribute_9: null,
      product_custom_attribute_10: null,
      description: "Reactive SQLite demo product",
    },
  };
}

export function useReactiveProducts() {
  const logStore = useLogStore();
  const isLoadingMore = ref(false);

  logStore.addLog("query", "Product reactive demo initialized");

  const { data: productStats, refetch: refetchStats } = useReactiveQuery(
    async () => {
      const row = await rdb
        .selectFrom("product_product as product")
        .select([
          sql<number>`count(*)`.as("total"),
          sql<number>`sum(case when product.sale_ok = 1 then 1 else 0 end)`.as("saleable"),
          sql<number>`sum(case when product.competitor_product = 1 then 1 else 0 end)`.as(
            "competitor",
          ),
        ])
        .where("product._delete_date", "is", null)
        .executeTakeFirst();

      return {
        total: Number(row?.total ?? 0),
        saleable: Number(row?.saleable ?? 0),
        competitor: Number(row?.competitor ?? 0),
      };
    },
    {
      tables: ["product_product"],
      queryKey: "reactive-products:stats",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 100,
      debug: false,
    },
  );

  const {
    data: products,
    loading,
    error,
    refetch: innerRefetch,
  } = useReactiveQuery(
    async () => {
      logStore.addLog("query", "SELECT product list with template relations");
      const startTime = performance.now();
      const rows = await fetchProductPage(productPageSize, 0);

      const elapsed = (performance.now() - startTime).toFixed(2);
      logStore.addLog("query", `${rows.length} products loaded in ${elapsed}ms`);

      return rows;
    },
    {
      tables: productTables,
      queryKey: "reactive-products:list",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 100,
      debug: false,
    },
  );

  const stats = computed(() => productStats.value ?? emptyStats);
  const totalProducts = computed(() => stats.value.total);
  const saleableProducts = computed(() => stats.value.saleable);
  const competitorProducts = computed(() => stats.value.competitor);
  const visibleProductCount = computed(() => products.value?.length ?? 0);
  const hasMoreProducts = computed(() => visibleProductCount.value < totalProducts.value);

  function createSnapshot(): ProductDemoSnapshot {
    return {
      products: [...(products.value ?? [])],
      stats: { ...stats.value },
    };
  }

  function restoreSnapshot(snapshot: ProductDemoSnapshot | undefined) {
    products.value = snapshot?.products ?? [];
    productStats.value = snapshot?.stats ?? emptyStats;
  }

  const { mutate: addProductAction, loading: isAdding } = useOptimisticMutation<
    {
      name: string;
      price: number;
      type: "consu" | "service" | "product";
      saleOk: boolean;
      competitor: boolean;
    },
    unknown,
    ProductDemoSnapshot
  >({
    table: "product_product",
    snapshot: createSnapshot,
    optimisticUpdate: (input) => {
      const item: ProductDemoItem = {
        id: -Date.now(),
        ruid: `optimistic-${Date.now()}`,
        templateRuid: null,
        name: input.name,
        defaultCode: "PENDING",
        listPrice: input.price,
        type: input.type,
        active: true,
        saleOk: input.saleOk,
        competitor: input.competitor,
        sequence: Date.now(),
        brandName: "Reactive Demo",
        categoryName: "Reactive Demo",
        uomName: "Unit",
        syncStatus: "synced",
      };

      products.value = [item, ...(products.value ?? [])];
      productStats.value = {
        total: stats.value.total + 1,
        saleable: stats.value.saleable + (input.saleOk ? 1 : 0),
        competitor: stats.value.competitor + (input.competitor ? 1 : 0),
      };
      logStore.addLog("mutation", `Optimistic product added: ${input.name}`);
    },
    mutation: async (input) => {
      const refs = await ensureDemoLookups();
      const rows = createProductRows({ ...input, refs });

      logStore.addLog("mutation", `INSERT product_product ${input.name}`);

      return await rdb.transaction().execute(async (trx) => {
        await trx
          .insertInto("product_template")
          .values(rows.template as any)
          .execute();
        return await trx
          .insertInto("product_product")
          .values(rows.product as any)
          .execute();
      });
    },
    rollback: (snapshot) => {
      restoreSnapshot(snapshot);
    },
    onError: (err) => {
      logStore.addLog(
        "mutation",
        `Add failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    },
    onSuccess: () => {
      logStore.addLog("event", "product_product insert event emitted");
    },
  });

  const { mutate: toggleSaleAction, loading: isTogglingSale } = useOptimisticMutation<
    number,
    unknown,
    ProductDemoSnapshot
  >({
    table: "product_product",
    snapshot: createSnapshot,
    optimisticUpdate: (id) => {
      const product = products.value?.find((item) => item.id === id);
      products.value =
        products.value?.map((product) =>
          product.id === id ? { ...product, saleOk: !product.saleOk } : product,
        ) ?? [];
      if (product) {
        productStats.value = {
          ...stats.value,
          saleable: stats.value.saleable + (product.saleOk ? -1 : 1),
        };
      }
      logStore.addLog("mutation", `Optimistic sale flag toggle #${id}`);
    },
    mutation: async (id) => {
      const product = products.value?.find((item) => item.id === id);
      const next = product?.saleOk ? 1 : 0;

      return await rdb
        .updateTable("product_product")
        .set({
          sale_ok: next as any,
          _write_date: nowISO(),
          _sync_status: "synced",
        })
        .where("id", "=", id)
        .execute();
    },
    rollback: (snapshot) => {
      restoreSnapshot(snapshot);
    },
    onError: (err) => {
      logStore.addLog(
        "mutation",
        `Sale toggle failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    },
  });

  const { mutate: toggleCompetitorAction, loading: isTogglingCompetitor } = useOptimisticMutation<
    number,
    unknown,
    ProductDemoSnapshot
  >({
    table: "product_product",
    snapshot: createSnapshot,
    optimisticUpdate: (id) => {
      const product = products.value?.find((item) => item.id === id);
      products.value =
        products.value?.map((product) =>
          product.id === id ? { ...product, competitor: !product.competitor } : product,
        ) ?? [];
      if (product) {
        productStats.value = {
          ...stats.value,
          competitor: stats.value.competitor + (product.competitor ? -1 : 1),
        };
      }
      logStore.addLog("mutation", `Optimistic competitor toggle #${id}`);
    },
    mutation: async (id) => {
      const product = products.value?.find((item) => item.id === id);
      const next = product?.competitor ? 1 : 0;

      return await rdb
        .updateTable("product_product")
        .set({
          competitor_product: next as any,
          _write_date: nowISO(),
          _sync_status: "synced",
        })
        .where("id", "=", id)
        .execute();
    },
    rollback: (snapshot) => {
      restoreSnapshot(snapshot);
    },
    onError: (err) => {
      logStore.addLog(
        "mutation",
        `Competitor toggle failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    },
  });

  const { mutate: renameProductAction, loading: isRenaming } = useOptimisticMutation<
    { id: number; name: string; price: number },
    unknown,
    ProductDemoSnapshot
  >({
    table: "product_product",
    snapshot: createSnapshot,
    optimisticUpdate: ({ id, name, price }) => {
      products.value =
        products.value?.map((product) =>
          product.id === id ? { ...product, name, listPrice: price } : product,
        ) ?? [];
      logStore.addLog("mutation", `Optimistic product edit #${id}`);
    },
    mutation: async ({ id, name, price }) => {
      const product = products.value?.find((item) => item.id === id);

      return await rdb.transaction().execute(async (trx) => {
        if (product?.templateRuid) {
          await trx
            .updateTable("product_template")
            .set({
              name,
              _write_date: nowISO(),
              _sync_status: "synced",
            } as any)
            .where("_ruid", "=", product.templateRuid)
            .execute();
        }

        return await trx
          .updateTable("product_product")
          .set({
            name,
            lst_price: price,
            standard_price: price,
            _write_date: nowISO(),
            _sync_status: "synced",
          } as any)
          .where("id", "=", id)
          .execute();
      });
    },
    rollback: (snapshot) => {
      restoreSnapshot(snapshot);
    },
    onError: (err) => {
      logStore.addLog(
        "mutation",
        `Edit failed: ${err instanceof Error ? err.message : String(err)}`,
      );
    },
  });

  async function injectRawProduct() {
    const refs = await ensureDemoLookups();
    const rows = createProductRows({
      name: `Raw Product ${new Date().toLocaleTimeString()}`,
      price: 25,
      type: "product",
      saleOk: true,
      competitor: false,
      refs,
    });
    const conn = await getRawConnection();

    await executeWithEvent("product_template", "insert", async () => {
      return await conn.run(
        `INSERT INTO product_template (
          _ruid, _create_date, _write_date, _delete_date, _sync_status,
          name, sale_ok, purchase_ok, type, brand_id, categ_id, taxes_id,
          competitor_product, uom_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          rows.template._ruid,
          rows.template._create_date,
          rows.template._write_date,
          rows.template._delete_date,
          rows.template._sync_status,
          rows.template.name,
          rows.template.sale_ok,
          rows.template.purchase_ok,
          rows.template.type,
          rows.template.brand_id,
          rows.template.categ_id,
          rows.template.taxes_id,
          rows.template.competitor_product,
          rows.template.uom_id,
        ],
      );
    });

    await executeWithEvent("product_product", "insert", async () => {
      return await conn.run(
        `INSERT INTO product_product (
          _ruid, _create_date, _write_date, _delete_date, _sync_status,
          name, default_code, barcode, color_code, custom_sequence,
          lst_price, standard_price, volume, weight, image_512, image_ids,
          type, product_tmpl_id, packaging_ids, uom_id, can_sale_in_uom,
          attachment_ids, competitor_product, active, warehouse_ids,
          suggested_price_ids, sale_ok, sub_product_ids, user_product_limit_ids,
          can_be_use_in_promotion, product_custom_attribute_1,
          product_custom_attribute_2, product_custom_attribute_3,
          product_custom_attribute_4, product_custom_attribute_5,
          product_custom_attribute_6, product_custom_attribute_7,
          product_custom_attribute_8, product_custom_attribute_9,
          product_custom_attribute_10, description
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          rows.product._ruid,
          rows.product._create_date,
          rows.product._write_date,
          rows.product._delete_date,
          rows.product._sync_status,
          rows.product.name,
          rows.product.default_code,
          rows.product.barcode,
          rows.product.color_code,
          rows.product.custom_sequence,
          rows.product.lst_price,
          rows.product.standard_price,
          rows.product.volume,
          rows.product.weight,
          rows.product.image_512,
          rows.product.image_ids,
          rows.product.type,
          rows.product.product_tmpl_id,
          rows.product.packaging_ids,
          rows.product.uom_id,
          rows.product.can_sale_in_uom,
          rows.product.attachment_ids,
          rows.product.competitor_product,
          rows.product.active,
          rows.product.warehouse_ids,
          rows.product.suggested_price_ids,
          rows.product.sale_ok,
          rows.product.sub_product_ids,
          rows.product.user_product_limit_ids,
          rows.product.can_be_use_in_promotion,
          rows.product.product_custom_attribute_1,
          rows.product.product_custom_attribute_2,
          rows.product.product_custom_attribute_3,
          rows.product.product_custom_attribute_4,
          rows.product.product_custom_attribute_5,
          rows.product.product_custom_attribute_6,
          rows.product.product_custom_attribute_7,
          rows.product.product_custom_attribute_8,
          rows.product.product_custom_attribute_9,
          rows.product.product_custom_attribute_10,
          rows.product.description,
        ],
      );
    });

    logStore.addLog("event", "Raw SQLite product injected");
    await refetchStats();
  }

  async function refetchProducts() {
    logStore.addLog("refetch", "Manual product refetch requested");
    await Promise.all([innerRefetch(), refetchStats()]);
  }

  async function loadMoreProducts() {
    if (isLoadingMore.value || !hasMoreProducts.value) return;

    isLoadingMore.value = true;
    const offset = products.value?.length ?? 0;
    const startTime = performance.now();

    try {
      const nextPage = await fetchProductPage(productPageSize, offset);
      const seenIds = new Set((products.value ?? []).map((product) => product.id));
      const uniqueProducts = nextPage.filter((product) => !seenIds.has(product.id));

      products.value = [...(products.value ?? []), ...uniqueProducts];

      const elapsed = (performance.now() - startTime).toFixed(2);
      logStore.addLog("query", `${uniqueProducts.length} more products loaded in ${elapsed}ms`);
    } finally {
      isLoadingMore.value = false;
    }
  }

  async function loadAllProducts() {
    if (isLoadingMore.value || !hasMoreProducts.value) return;

    isLoadingMore.value = true;
    const startTime = performance.now();

    try {
      const seenIds = new Set((products.value ?? []).map((product) => product.id));
      const nextProducts = [...(products.value ?? [])];
      let offset = nextProducts.length;

      while (offset < totalProducts.value) {
        const nextPage = await fetchProductPage(productPageSize, offset);
        if (nextPage.length === 0) break;

        for (const product of nextPage) {
          if (!seenIds.has(product.id)) {
            seenIds.add(product.id);
            nextProducts.push(product);
          }
        }

        offset += nextPage.length;
      }

      products.value = nextProducts;

      const elapsed = (performance.now() - startTime).toFixed(2);
      logStore.addLog("query", `${nextProducts.length} products ready for search in ${elapsed}ms`);
    } finally {
      isLoadingMore.value = false;
    }
  }

  return {
    products,
    totalProducts,
    saleableProducts,
    competitorProducts,
    visibleProductCount,
    hasMoreProducts,
    loading,
    isLoadingMore,
    error,
    isAdding,
    isTogglingSale,
    isTogglingCompetitor,
    isRenaming,
    addProduct: addProductAction,
    toggleSale: toggleSaleAction,
    toggleCompetitor: toggleCompetitorAction,
    renameProduct: renameProductAction,
    injectRawProduct,
    loadMoreProducts,
    loadAllProducts,
    refetch: refetchProducts,
  };
}
